// Configuration du workflow « Qualification ».
// C'est le seul nœud à modifier après l'import : renseigne les ID des listes
// Brevo affichés par scripts/setup_brevo.py.
const config = {
  marque: 'Pacewell',
  modele: 'claude-haiku-5-5',
  // Tarifs Claude Haiku 5.5 (USD par million de tokens, prompts < 100k tokens).
  // Source : platform.claude.com/docs/en/about-claude/pricing — à revérifier de temps en temps.
  prixEntreeParMillion: 0.10,
  prixSortieParMillion: 0.50,
  seuilLeadChaud: 70,
  emailAlerte: 'simon59117@gmail.com',
  // Alertes et validations (vers toi) / emails aux inscrits (au nom de la marque).
  expediteur: { email: 'audit@simondelrue.fr', name: 'Pacewell CRM' },
  expediteurMarque: { email: 'audit@simondelrue.fr', name: 'Pacewell' },
  urlSite: 'https://pacewell.simondelrue.fr',
  urlN8n: 'https://n8n.simondelrue.fr',
  // Réactivation : inactif depuis N jours, au plus M propositions par passage.
  joursInactivite: 60,
  maxRelances: 5,
  delaiDoublonJours: 7,
  // Adresses des API (modifiables pour les tests).
  urlBrevo: 'https://api.brevo.com/v3',
  urlClaude: 'https://api.anthropic.com/v1',
  listes: {
    ROUTE_DEBUTANT: 0,
    ROUTE_PERF: 0,
    TRAIL_DECOUVERTE: 0,
    TRAIL_ENDURANCE: 0,
    A_QUALIFIER: 0,
  },
};

// Le webhook range le formulaire dans `body` et les paramètres d'URL dans `query`.
return { formulaire: $json.body ?? {}, query: $json.query ?? {}, config };

// Évaluation : produit un élément par profil annoté (mode « une fois pour tous les éléments »).
// La liste est injectée depuis evaluation/profils.json par construire_workflow.py.
const PROFILS = [{"id": 1, "pratique": "route", "frequence": "moins-1", "objectif": "forme", "budget": "moins-150", "attendu": {"segment": "ROUTE_DEBUTANT", "temperatures": ["froid"]}, "note": "Reprise très légère, petit budget"}, {"id": 2, "pratique": "route", "frequence": "1-2", "objectif": "10km", "budget": "moins-150", "attendu": {"segment": "ROUTE_DEBUTANT", "temperatures": ["froid"]}, "note": "Débutant 10 km, petit budget"}, {"id": 3, "pratique": "route", "frequence": "1-2", "objectif": "forme", "budget": "150-400", "attendu": {"segment": "ROUTE_DEBUTANT", "temperatures": ["froid", "tiede"]}, "note": "Forme, budget moyen"}, {"id": 4, "pratique": "route", "frequence": "1-2", "objectif": "10km", "budget": "400-plus", "attendu": {"segment": "ROUTE_DEBUTANT", "temperatures": ["tiede"]}, "note": "Débutant mais gros budget"}, {"id": 5, "pratique": "route", "frequence": "moins-1", "objectif": "10km", "budget": "150-400", "attendu": {"segment": "ROUTE_DEBUTANT", "temperatures": ["froid", "tiede"]}, "note": "Occasionnel, budget moyen"}, {"id": 6, "pratique": "route", "frequence": "3-4", "objectif": "10km", "budget": "150-400", "attendu": {"segment": "ROUTE_PERF", "temperatures": ["tiede"]}, "note": "10 km régulier"}, {"id": 7, "pratique": "route", "frequence": "1-2", "objectif": "semi", "budget": "150-400", "attendu": {"segment": "ROUTE_PERF", "temperatures": ["tiede"]}, "note": "Semi, objectif chronométré"}, {"id": 8, "pratique": "route", "frequence": "3-4", "objectif": "marathon", "budget": "400-plus", "attendu": {"segment": "ROUTE_PERF", "temperatures": ["chaud"]}, "note": "Marathonien équipé"}, {"id": 9, "pratique": "route", "frequence": "5-plus", "objectif": "marathon", "budget": "400-plus", "attendu": {"segment": "ROUTE_PERF", "temperatures": ["chaud"]}, "note": "Marathonien intensif"}, {"id": 10, "pratique": "route", "frequence": "5-plus", "objectif": "semi", "budget": "150-400", "attendu": {"segment": "ROUTE_PERF", "temperatures": ["tiede", "chaud"]}, "note": "Très régulier, budget moyen"}, {"id": 11, "pratique": "route", "frequence": "3-4", "objectif": "forme", "budget": "moins-150", "attendu": {"segment": "ROUTE_PERF", "temperatures": ["froid", "tiede"]}, "note": "Régulier sans objectif, petit budget"}, {"id": 12, "pratique": "route", "frequence": "1-2", "objectif": "marathon", "budget": "moins-150", "attendu": {"segment": "ROUTE_PERF", "temperatures": ["froid", "tiede"]}, "note": "Marathon ambitieux, petit budget"}, {"id": 13, "pratique": "trail", "frequence": "moins-1", "objectif": "forme", "budget": "moins-150", "attendu": {"segment": "TRAIL_DECOUVERTE", "temperatures": ["froid"]}, "note": "Curieux du trail"}, {"id": 14, "pratique": "trail", "frequence": "1-2", "objectif": "trail-court", "budget": "150-400", "attendu": {"segment": "TRAIL_DECOUVERTE", "temperatures": ["tiede"]}, "note": "Premier trail court"}, {"id": 15, "pratique": "trail", "frequence": "1-2", "objectif": "forme", "budget": "400-plus", "attendu": {"segment": "TRAIL_DECOUVERTE", "temperatures": ["tiede"]}, "note": "Balades trail, gros budget"}, {"id": 16, "pratique": "trail", "frequence": "moins-1", "objectif": "trail-court", "budget": "moins-150", "attendu": {"segment": "TRAIL_DECOUVERTE", "temperatures": ["froid"]}, "note": "Occasionnel, petit budget"}, {"id": 17, "pratique": "trail", "frequence": "1-2", "objectif": "trail-court", "budget": "moins-150", "attendu": {"segment": "TRAIL_DECOUVERTE", "temperatures": ["froid", "tiede"]}, "note": "Trail court, petit budget"}, {"id": 18, "pratique": "trail", "frequence": "3-4", "objectif": "trail-court", "budget": "400-plus", "attendu": {"segment": "TRAIL_ENDURANCE", "temperatures": ["chaud"]}, "note": "Traileur régulier équipé"}, {"id": 19, "pratique": "trail", "frequence": "3-4", "objectif": "ultra", "budget": "400-plus", "attendu": {"segment": "TRAIL_ENDURANCE", "temperatures": ["chaud"]}, "note": "Ultra, profil idéal"}, {"id": 20, "pratique": "trail", "frequence": "5-plus", "objectif": "ultra", "budget": "400-plus", "attendu": {"segment": "TRAIL_ENDURANCE", "temperatures": ["chaud"]}, "note": "Ultra intensif"}, {"id": 21, "pratique": "trail", "frequence": "1-2", "objectif": "ultra", "budget": "150-400", "attendu": {"segment": "TRAIL_ENDURANCE", "temperatures": ["tiede"]}, "note": "Ultra mais peu de sorties"}, {"id": 22, "pratique": "trail", "frequence": "3-4", "objectif": "forme", "budget": "150-400", "attendu": {"segment": "TRAIL_ENDURANCE", "temperatures": ["tiede"]}, "note": "Régulier sans objectif"}, {"id": 23, "pratique": "trail", "frequence": "5-plus", "objectif": "trail-court", "budget": "150-400", "attendu": {"segment": "TRAIL_ENDURANCE", "temperatures": ["tiede", "chaud"]}, "note": "Très régulier, budget moyen"}, {"id": 24, "pratique": "les-deux", "frequence": "1-2", "objectif": "forme", "budget": "moins-150", "attendu": {"segment": "ROUTE_DEBUTANT", "temperatures": ["froid"]}, "note": "Mixte, forme, petit budget"}, {"id": 25, "pratique": "les-deux", "frequence": "3-4", "objectif": "marathon", "budget": "400-plus", "attendu": {"segment": "ROUTE_PERF", "temperatures": ["chaud"]}, "note": "Mixte, marathon, équipé"}, {"id": 26, "pratique": "les-deux", "frequence": "1-2", "objectif": "10km", "budget": "150-400", "attendu": {"segment": "ROUTE_DEBUTANT", "temperatures": ["froid", "tiede"]}, "note": "Mixte, 10 km"}, {"id": 27, "pratique": "les-deux", "frequence": "1-2", "objectif": "trail-court", "budget": "150-400", "attendu": {"segment": "TRAIL_DECOUVERTE", "temperatures": ["tiede"]}, "note": "Mixte, découvre le trail"}, {"id": 28, "pratique": "les-deux", "frequence": "3-4", "objectif": "ultra", "budget": "400-plus", "attendu": {"segment": "TRAIL_ENDURANCE", "temperatures": ["chaud"]}, "note": "Mixte, ultra"}, {"id": 29, "pratique": "les-deux", "frequence": "5-plus", "objectif": "trail-court", "budget": "400-plus", "attendu": {"segment": "TRAIL_ENDURANCE", "temperatures": ["chaud"]}, "note": "Mixte intensif, trail"}, {"id": 30, "pratique": "les-deux", "frequence": "moins-1", "objectif": "semi", "budget": "moins-150", "attendu": {"segment": "ROUTE_PERF", "temperatures": ["froid"]}, "note": "Semi visé, très peu de sorties"}];
return PROFILS.map((p) => ({
  json: {
    profil: p,
    lead: { email: 'evaluation@exemple.fr', prenom: '', pratique: p.pratique, frequence: p.frequence, objectif: p.objectif, budget: p.budget },
  },
}));

// Prépare la requête envoyée à Claude.
// Minimisation des données (RGPD) : l'IA ne reçoit NI l'email NI le prénom,
// seulement les réponses au questionnaire.
const { lead } = $json;
const { config } = $('Configuration').item.json;

const consignes = `Tu es l'outil de qualification CRM de ${config.marque}, une boutique en ligne de running et de trail.
À partir des réponses d'un nouvel inscrit, tu le classes pour personnaliser ses emails.

Segments possibles (choisis-en exactement un) :
- ROUTE_DEBUTANT : court sur route, débute ou reprend, objectif forme ou 10 km, 2 sorties par semaine maximum.
- ROUTE_PERF : court sur route avec un objectif chronométré (semi, marathon) ou 3 sorties et plus par semaine.
- TRAIL_DECOUVERTE : découvre le trail, objectif forme ou trail court, pratique occasionnelle à régulière.
- TRAIL_ENDURANCE : trail engagé, objectif ultra, ou trail avec 3 sorties et plus par semaine.
Règles : « route » donne toujours un segment ROUTE_*, « trail » toujours un segment TRAIL_*.
Pour « les-deux », l'objectif tranche (trail-court ou ultra : TRAIL_* ; sinon ROUTE_*).

Niveau : debutant, intermediaire ou confirme.
Score de 1 à 100 : potentiel commercial sur un an (fréquence de pratique, budget annuel, ambition de l'objectif).
Repères : moins d'une sortie et budget faible, autour de 15 ; pratique régulière et budget moyen, autour de 50 ;
pratique intensive, budget élevé et objectif ambitieux, au-delà de 80.

Réponds UNIQUEMENT avec un objet JSON, sans texte autour :
{"segment": "...", "niveau": "...", "score": 0, "raison": "une phrase de 25 mots maximum"}`;

const reponses = {
  pratique: lead.pratique,
  sorties_par_semaine: lead.frequence,
  objectif: lead.objectif,
  budget_annuel_equipement_euros: lead.budget,
};

return {
  requete: {
    model: config.modele,
    max_tokens: 600,
    // Tâche courte : pas de réflexion préalable, sinon elle peut consommer tout le budget de tokens.
    thinking: { type: 'disabled' },
    system: consignes,
    messages: [{ role: 'user', content: 'Réponses du formulaire :\n' + JSON.stringify(reponses, null, 1) }],
  },
};

// Valide la réponse de Claude. Garde-fou principal du workflow :
// toute réponse absente, illisible ou incohérente envoie le contact
// dans le segment par défaut A_QUALIFIER, avec la raison du repli.
const SEGMENTS = ['ROUTE_DEBUTANT', 'ROUTE_PERF', 'TRAIL_DECOUVERTE', 'TRAIL_ENDURANCE'];
const NIVEAUX = ['debutant', 'intermediaire', 'confirme'];
const { lead } = $('Profils annotés').item.json;
const { config } = $('Configuration').item.json;

const repli = (motif, cout = 0) => ({
  lead,
  qualification: {
    segment: 'A_QUALIFIER', niveau: '', score: 0,
    raison: `Qualification automatique impossible (${motif}).`,
    source: 'repli', cout_usd: cout,
  },
});

const statut = $json.statusCode;
const corps = $json.body || {};
const usage = corps.usage || {};
const cout = ((usage.input_tokens || 0) * config.prixEntreeParMillion
  + (usage.output_tokens || 0) * config.prixSortieParMillion) / 1e6;

if (statut !== 200) {
  return repli(`API ${statut || 'injoignable'}`, 0);
}

const texte = (corps.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
let r;
try {
  const debut = texte.indexOf('{');
  const fin = texte.lastIndexOf('}');
  r = JSON.parse(texte.slice(debut, fin + 1));
} catch (e) {
  return repli('JSON illisible', cout);
}

const score = Number(r.score);
if (!SEGMENTS.includes(r.segment)) return repli('segment inconnu', cout);
if (!NIVEAUX.includes(r.niveau)) return repli('niveau inconnu', cout);
if (!Number.isInteger(score) || score < 1 || score > 100) return repli('score hors bornes', cout);
if (typeof r.raison !== 'string' || !r.raison.trim()) return repli('raison absente', cout);
// Cohérence avec les réponses : l'IA ne peut pas classer un coureur sur route dans le trail.
if (lead.pratique === 'route' && !r.segment.startsWith('ROUTE')) return repli('segment incohérent', cout);
if (lead.pratique === 'trail' && !r.segment.startsWith('TRAIL')) return repli('segment incohérent', cout);

return {
  lead,
  qualification: {
    segment: r.segment, niveau: r.niveau, score,
    raison: r.raison.trim().slice(0, 250),
    source: 'ia', cout_usd: Math.round(cout * 1e6) / 1e6,
  },
};

// Évaluation : compare chaque qualification à l'annotation (mode « une fois pour tous les éléments »).
const { config } = $('Configuration').first().json;
const profils = $('Profils annotés').all().map((i) => i.json.profil);
const temperature = (score) => (score >= 70 ? 'chaud' : score >= 40 ? 'tiede' : 'froid');

const details = $input.all().map((i, k) => {
  const p = profils[k];
  const q = i.json.qualification;
  const t = temperature(q.score);
  return {
    id: p.id, profil: `${p.pratique} · ${p.frequence} · ${p.objectif} · ${p.budget}`, note: p.note,
    attendu: p.attendu, obtenu: { segment: q.segment, score: q.score, temperature: t, source: q.source, raison: q.raison },
    segmentCorrect: q.segment === p.attendu.segment,
    temperatureCorrecte: q.source === 'ia' && p.attendu.temperatures.includes(t),
    coutUsd: q.cout_usd,
  };
});
const somme = (f) => details.reduce((s, d) => s + f(d), 0);
return [{
  json: {
    date: new Date().toISOString().slice(0, 10),
    modele: config.modele,
    profils: details.length,
    segmentsCorrects: somme((d) => (d.segmentCorrect ? 1 : 0)),
    temperaturesCorrectes: somme((d) => (d.temperatureCorrecte ? 1 : 0)),
    replis: somme((d) => (d.obtenu.source === 'repli' ? 1 : 0)),
    coutTotalUsd: Math.round(somme((d) => d.coutUsd) * 1e6) / 1e6,
    details,
  },
}];
